using System.Data;using System.Text;using Dapper;using Microsoft.Data.SqlClient;using Microsoft.Extensions.Configuration;using GraphApi.Models.FNZ.Cuotas;namespace GraphApi.Services.FNZ.Cuotas{    public class CuotasService : ICuotasService    {        private readonly IDbConnection   _objDbDefault;        private readonly IConfiguration  _objConfig;        public CuotasService(IDbConnection objDbDefault, IConfiguration objConfig)        {            _objDbDefault = objDbDefault;            _objConfig    = objConfig;        }        public async Task<IEnumerable<clReadCuotas>> GetCuotas(            int userId,            string windowName)        {            var vSql = new StringBuilder($@"                --WindowName:{windowName},UserID:{userId}                SELECT  *                 FROM fnz.Cuotas (NOLOCK)            ");            var vParameters = new DynamicParameters();            var vList = await _objDbDefault.QueryAsync<clReadCuotas>(vSql.ToString(), vParameters);            return vList;        }        public async Task<IEnumerable<dynamic>> GetCuotasDynamic(            int? cuotaID,            int? usuarioID,            int? casaID,            decimal? monto,            DateTime? periodoInicio,            DateTime? periodoFin,            DateTime? fechaVencimiento,            bool? pagado,            DateTime? fechaPago,            string? metodoPago,            string? referenciaPago,            bool? bEliminado,            string? columnNames,            int userId,            string windowName)        {            string sColumnNames = string.IsNullOrWhiteSpace(columnNames) ? "CuotaID, UsuarioID, CasaID, Monto, PeriodoInicio, PeriodoFin, FechaVencimiento, Pagado, FechaPago, MetodoPago, ReferenciaPago, bEliminado" : columnNames;            var vSql = new StringBuilder($@"                --WindowName:{windowName},UserID:{userId}                SELECT {sColumnNames}                FROM fnz.Cuotas (NOLOCK)                WHERE 1=1            ");            var vParameters = new DynamicParameters();            if (cuotaID.HasValue)            {                vSql.Append(" AND CuotaID = @CuotaID");                vParameters.Add("CuotaID",cuotaID);            }            if (pagado.HasValue)            {                vSql.Append(" AND Pagado = @Pagado");                vParameters.Add("Pagado", pagado.Value);            }            if (!string.IsNullOrWhiteSpace(metodoPago))            {                vSql.Append(" AND MetodoPago LIKE @MetodoPago");                vParameters.Add("MetodoPago",$"%{metodoPago}%");            }            if (!string.IsNullOrWhiteSpace(referenciaPago))            {                vSql.Append(" AND ReferenciaPago LIKE @ReferenciaPago");                vParameters.Add("ReferenciaPago",$"%{referenciaPago}%");            }            if (bEliminado.HasValue)            {                vSql.Append(" AND bEliminado = @bEliminado");                vParameters.Add("bEliminado", bEliminado.Value);            }            var vList = await _objDbDefault.QueryAsync<dynamic>(vSql.ToString(), vParameters);            return vList;        }        public async Task<clReadCuotas> CreateCuotas(clCreateCuotas objInput, int userId, string windowName)        {            string sInsertSql = $@"                --WindowName:{windowName},UserID:{userId}                INSERT INTO fnz.Cuotas                (UsuarioID, CasaID, Monto, PeriodoInicio, PeriodoFin, FechaVencimiento, Pagado, FechaPago, MetodoPago, ReferenciaPago, bEliminado, Creado, UsuarioCreacionID, FechaCreacion)                VALUES (@UsuarioID, @CasaID, @Monto, @PeriodoInicio, @PeriodoFin, @FechaVencimiento, @Pagado, @FechaPago, @MetodoPago, @ReferenciaPago, @bEliminado, @Creado, @UsuarioCreacionID, GETDATE());                SELECT CAST(SCOPE_IDENTITY() AS INT);            ";            var vInsertParams = new            {                objInput.UsuarioID,                objInput.CasaID,                objInput.Monto,                objInput.PeriodoInicio,                objInput.PeriodoFin,                objInput.FechaVencimiento,                objInput.Pagado,                objInput.FechaPago,                objInput.MetodoPago,                objInput.ReferenciaPago,                objInput.bEliminado,                Creado     = windowName,                UsuarioCreacionID = userId            };            var vNewId = await _objDbDefault.ExecuteScalarAsync<int>(sInsertSql, vInsertParams);            string sSelectSql = @"                SELECT CuotaID, UsuarioID, CasaID, Monto, PeriodoInicio, PeriodoFin, FechaVencimiento, Pagado, FechaPago, MetodoPago, ReferenciaPago, bEliminado                FROM fnz.Cuotas (NOLOCK)                WHERE CuotaID = @CuotaID;";            var vReadParams = new { CuotaID = vNewId };            var vCreated = await _objDbDefault.QuerySingleOrDefaultAsync<clReadCuotas>(sSelectSql, vReadParams);            if (vCreated is null) throw new InvalidOperationException($"No se pudo recuperar el Cuota con ID {vNewId}.");            return vCreated;        }        public async Task<clReadCuotas?> UpdateCuotas(clUpdateCuotas objInput, int userId, string windowName)        {            var vSets = new List<string>();            var vParameters = new DynamicParameters();            vParameters.Add("CuotaID", objInput.CuotaID);            if (objInput.UsuarioID != null)            {                vSets.Add("UsuarioID = @UsuarioID");                vParameters.Add("UsuarioID", objInput.UsuarioID);            }            if (objInput.CasaID != null)            {                vSets.Add("CasaID = @CasaID");                vParameters.Add("CasaID", objInput.CasaID);            }            if (objInput.Monto != null)            {                vSets.Add("Monto = @Monto");                vParameters.Add("Monto", objInput.Monto);            }            if (objInput.PeriodoInicio != null)            {                vSets.Add("PeriodoInicio = @PeriodoInicio");                vParameters.Add("PeriodoInicio", objInput.PeriodoInicio);            }            if (objInput.PeriodoFin != null)            {                vSets.Add("PeriodoFin = @PeriodoFin");                vParameters.Add("PeriodoFin", objInput.PeriodoFin);            }            if (objInput.FechaVencimiento != null)            {                vSets.Add("FechaVencimiento = @FechaVencimiento");                vParameters.Add("FechaVencimiento", objInput.FechaVencimiento);            }            if (objInput.Pagado != null)            {                vSets.Add("Pagado = @Pagado");                vParameters.Add("Pagado", objInput.Pagado);            }            if (objInput.FechaPago != null)            {                vSets.Add("FechaPago = @FechaPago");                vParameters.Add("FechaPago", objInput.FechaPago);            }            if (objInput.MetodoPago is not null)            {                vSets.Add("MetodoPago = @MetodoPago");                vParameters.Add("MetodoPago", objInput.MetodoPago);            }            if (objInput.ReferenciaPago is not null)            {                vSets.Add("ReferenciaPago = @ReferenciaPago");                vParameters.Add("ReferenciaPago", objInput.ReferenciaPago);            }            if (objInput.bEliminado != null)            {                vSets.Add("bEliminado = @bEliminado");                vParameters.Add("bEliminado", objInput.bEliminado);            }            vSets.Add($"Modificado = '{windowName}'");            vSets.Add($"UsuarioModificacionID = {userId}");            vSets.Add("FechaModificacion = GETDATE()");            var vSetClause = string.Join(", ", vSets);            var sSql = $@"                --WindowName:{windowName},UserID:{userId}                UPDATE fnz.Cuotas                SET {vSetClause}                WHERE CuotaID = @CuotaID;";            var vAffected = await _objDbDefault.ExecuteAsync(sSql, vParameters);            if (vAffected == 0) return null;            const string sSelect = @"                SELECT CuotaID, UsuarioID, CasaID, Monto, PeriodoInicio, PeriodoFin, FechaVencimiento, Pagado, FechaPago, MetodoPago, ReferenciaPago, bEliminado                FROM fnz.Cuotas (NOLOCK)                WHERE CuotaID = @CuotaID;";            return await _objDbDefault.QueryFirstOrDefaultAsync<clReadCuotas>(sSelect, new {  objInput.CuotaID });        }        public async Task<bool> DeleteCuotas(int nCuotasID)        {            const string sSql = @"                DELETE FROM fnz.Cuotas                WHERE CuotaID = @Id;";            var vAffected = await _objDbDefault.ExecuteAsync(sSql, new { Id = nCuotasID });            return vAffected > 0;        }    }}